import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

class Solution {
    private static class Pair {
        int firstIndex;
        int secondIndex;
        Pair(int firstIndex, int secondIndex) {
            this.firstIndex = firstIndex;
            this.secondIndex = secondIndex;
        }
    }

    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        PriorityQueue<Pair> heap = new PriorityQueue<>((first, second) -> {
            long firstSum = (long) nums1[first.firstIndex] + nums2[first.secondIndex];
            long secondSum = (long) nums1[second.firstIndex] + nums2[second.secondIndex];
            int bySum = Long.compare(firstSum, secondSum);
            if (bySum != 0) return bySum;
            int byFirstIndex = Integer.compare(first.firstIndex, second.firstIndex);
            return byFirstIndex != 0 ? byFirstIndex : Integer.compare(first.secondIndex, second.secondIndex);
        });
        int rows = Math.min(k, nums1.length);
        for (int row = 0; row < rows; row++) heap.offer(new Pair(row, 0));

        List<List<Integer>> result = new ArrayList<>();
        while (result.size() < k && !heap.isEmpty()) {
            Pair smallest = heap.poll();
            result.add(java.util.Arrays.asList(nums1[smallest.firstIndex], nums2[smallest.secondIndex]));
            int nextColumn = smallest.secondIndex + 1;
            if (nextColumn < nums2.length) {
                heap.offer(new Pair(smallest.firstIndex, nextColumn));
            }
        }
        return result;
    }
}
